function amplification(R, L) {
  let everyLayer = 1;
  for (let i = 0; i < L; i++) everyLayer *= R; // R^L
  const singleLayer = R * 1; // retry only at one hop
  return { everyLayer, singleLayer };
}
const R = 3, L = 4;
const { everyLayer, singleLayer } = amplification(R, L);
console.log('every-layer: ' + everyLayer);
console.log('single-layer: ' + singleLayer);
